            if a[i] > b[i]:
                ttb_pred = 0
                break
            elif b[i] > a[i]:
                ttb_pred = 1
                break

        if ttb_pred != -1:
            agreements.append(1.0 if resp == ttb_pred else 0.0)

    return float(np.mean(agreements)) if agreements else 0.0

